<template><ElConfigProvider namespace="kel"><section class="native-execution"><header class="native-execution-heading"><div class="execution-identity"><button class="native-back" aria-label="返回执行记录" @click="emit('navigate','/flows/executions')">←</button><div><h1>{{execution.flow_name||execution.engine_flow_id}}<KsExecutionStatus v-if="engineState!=='unknown'" :status="engineState" size="small"/></h1><div class="native-meta"><code>{{execution.id}}</code><span>Revision {{execution.flow_revision}}</span><span>{{execution.source_module}}</span></div></div></div><div class="native-execution-actions"><KsButton size="small" :disabled="!insights?.previous_id" @click="emit('navigate','/flows/executions/'+insights.previous_id)">上一条</KsButton><KsButton size="small" :disabled="!insights?.next_id" @click="emit('navigate','/flows/executions/'+insights.next_id)">下一条</KsButton><KsButton v-if="execution.flow_id" size="small" @click="emit('navigate','/flows/definitions/'+execution.flow_id+'?tab=Revisions')">源版本</KsButton><KsButton v-for="action in actions.filter(a=>a.states.includes(engineState))" :key="action.id" size="small" :type="action.id==='retry-failed-targets'?'primary':'default'" :disabled="!canExecute||busy||(action.id==='retry-failed-targets'&&!counts.FAILED)" @click="emit('action',action.id)">{{action.label}}</KsButton></div></header>
<div class="execution-meta"><div><small>开始时间</small><strong>{{date(execution.engine?.state?.startDate||execution.created_at)}}</strong></div><div><small>运行耗时</small><strong>{{elapsed(execution.engine?.state)}}<span>秒</span></strong></div><div><small>设备结果</small><strong class="result-summary"><span v-for="(count,state) in counts" :key="state" :class="String(state).toLowerCase()"><i/>{{count}} <small>{{state}}</small></span><span v-if="!execution.targets.length">无设备目标</span></strong></div><div><small>实际执行通道</small><strong>Agent {{execution.targets.filter(t=>t.actual_transport==='AGENT').length}} / SSH {{execution.targets.filter(t=>t.actual_transport==='SSH').length}}</strong></div><div class="meta-timeline"><small>状态历史</small><div class="state-line"><span v-for="(item,index) in execution.engine?.state?.histories||[]" :key="index" :title="date(item.date)">{{item.state}}<i v-if="index<(execution.engine.state.histories.length-1)"/></span><span v-if="!execution.engine?.state?.histories?.length">尚未采集</span></div></div></div>
<nav class="native-context-tabs"><button v-for="t in tabs" :key="t[0]" :class="{active:tab===t[0]}" @click="emit('tab',t[0])">{{t[1]}}</button><select aria-label="更多执行视图" :value="more.some(t=>t[0]===tab)?tab:''" @change="emit('tab',($event.target as HTMLSelectElement).value)"><option value="" disabled>更多</option><option v-for="t in more" :key="t[0]" :value="t[0]">{{t[1]}}</option></select></nav>
<div v-if="error" class="native-error" role="alert">{{error}}</div>
<template v-if="tab==='Overview'||tab==='Task Runs'"><div class="native-runtime-workspace"><main><div class="native-section-title"><div class="runtime-segment"><button :class="{active:!graph}" @click="graph=false">Gantt</button><button :class="{active:graph}" @click="graph=true">Topology</button></div><span>{{tasks.length}} tasks · {{elapsed(execution.engine?.state)}}s</span></div><div v-if="graph" class="runtime-topology"><NativePanelSlot name="topology" :attach="attach"/></div><div v-else class="native-gantt"><div class="native-gantt-header"><span>Task</span><div><span v-for="tick in ticks" :key="tick">{{tick}}s</span></div></div><button v-for="task in tasks" :key="task.id" class="native-gantt-row" :class="{selected:context.task_run===task.id}" @click="emit('context','task_run',task.id)"><span class="gantt-task-name"><i :class="String(task.state?.current).toLowerCase()"/><span><b>{{task.taskId}}</b><small>{{task.value??task.state?.current??'未知'}} · {{task.attempts?.length||0}} attempts</small></span></span><div class="native-gantt-track"><i v-if="Number.isFinite(Date.parse(task.state?.startDate))" :class="String(task.state?.current).toLowerCase()" :style="bar(task)"><span>{{elapsed(task.state)}}s</span></i><i v-else class="unobserved" title="尚无实际开始时间"/></div></button><div v-if="!tasks.length" class="native-empty">引擎尚未产生 TaskRun</div><div class="gantt-legend"><span><i class="success"/>成功</span><span><i class="failed"/>失败</span><span><i class="blocked"/>待执行 / 阻断</span><small>点击任务查看 Attempt 与日志</small></div></div><section class="inline-task-logs"><div class="native-section-title"><h3>任务日志 <code>{{selectedTask?.taskId||'当前执行'}}</code></h3><button class="text-link" @click="emit('tab','Logs')">展开日志 →</button></div><div v-for="(line,index) in filteredLogs.slice(-6)" :key="line.id||index" class="inline-log-line"><time>{{date(line.timestamp)}}</time><b :class="String(line.level).toLowerCase()">{{line.level}}</b><code>{{line.message}}</code></div><p v-if="!filteredLogs.length" class="log-empty">暂无当前任务已采集日志</p></section></main><aside class="native-runtime-inspector"><div class="native-section-title"><b>TASK RUN</b><KsExecutionStatus v-if="selectedTask?.state?.current" :status="selectedTask.state.current" size="small"/></div><template v-if="selectedTask"><h3>{{selectedTask.taskId}}</h3><small class="task-iteration">{{selectedTask.value||'当前任务实例'}}</small><dl><dt>Task Run</dt><dd>{{selectedTask.id}}</dd><dt>开始时间</dt><dd>{{date(selectedTask.state?.startDate)}}</dd><dt>持续时间</dt><dd>{{elapsed(selectedTask.state)}} s</dd><dt>Attempts</dt><dd>{{selectedTask.attempts?.length||0}}</dd><dt>执行版本</dt><dd>revision {{execution.flow_revision}}</dd><dt>Worker</dt><dd>{{selectedTask.workerId||'未上报'}}</dd></dl><h4>Attempts</h4><button v-for="(item,index) in selectedTask.attempts||[]" :key="index" :class="['native-attempt',{active:Number(context.attempt)===index+1}]" @click="emit('context','attempt',String(index+1))"><span><b>#{{index+1}}</b> {{index?'重试':'首次执行'}}</span><KsExecutionStatus v-if="item.state?.current" :status="item.state.current" size="small"/><time>{{date(item.state?.startDate)}} → {{date(item.state?.endDate)}}</time><pre v-if="item.error">{{JSON.stringify(item.error,null,2)}}</pre></button><div v-if="selectedTask.state?.current==='FAILED'" class="task-error"><b>任务失败</b><pre>{{selectedError||'查看当前任务日志和退出证据以定位原因。'}}</pre></div><button class="text-link attempt-log-link" @click="emit('tab','Logs')">查看{{context.attempt?' Attempt '+context.attempt:''}}日志 →</button><button class="text-link attempt-log-link" @click="emit('tab','Outputs & Artifacts')">查看变量与输出 →</button></template><p v-else class="log-empty">选择任务以查看迭代、Attempt 和关联日志。</p></aside></div></template>
<template v-else-if="tab==='Targets'"><div class="native-filters"><KsInput v-model="targetQuery" placeholder="搜索设备名称或资产 ID"/><select v-model="targetState"><option value="">所有结果</option><option v-for="state in Object.keys(counts)" :key="state">{{state}}</option></select><KsButton size="small" @click="matrix=!matrix">{{matrix?'Table':'Status Matrix'}}</KsButton></div><div class="native-target-workspace"><main><div v-if="matrix" class="native-target-matrix"><button v-for="target in visibleTargets" :key="target.id" :class="['native-target',target.state.toLowerCase(),{selected:context.target===target.id}]" @click="emit('context','target',target.id)"><b>{{target.snapshot.name||target.id}}</b><span>{{target.state}}</span><small>{{target.actual_transport||'未选通道'}} · exit {{target.exit_code??'—'}}</small></button></div><KsDataTable v-else :data="visibleTargets" :total="visibleTargets.length" :selectable="false" :showPagination="false" rowKey="id" @row-click="row=>emit('context','target',row.id)"><KsTableColumn label="设备 / 资产"><template #default="{row}"><b>{{row.snapshot.name}}</b><small>{{row.id}}</small></template></KsTableColumn><KsTableColumn prop="state" label="结果"/><KsTableColumn prop="actual_transport" label="通道"/><KsTableColumn prop="attempt" label="Attempt"/><KsTableColumn prop="exit_code" label="Exit"/></KsDataTable><div v-if="!visibleTargets.length" class="native-empty">没有符合条件的目标</div></main><aside class="native-runtime-inspector"><div class="native-section-title">SELECTED TARGET</div><template v-if="selectedTarget"><h3>{{selectedTarget.snapshot.name}}</h3><button class="native-link" @click="emit('navigate','/cmdb?asset='+encodeURIComponent(selectedTarget.id))">{{selectedTarget.id}} → CMDB</button><dl><dt>Agent</dt><dd>{{selectedTarget.snapshot.agent_id||'—'}}</dd><dt>SSH Trust</dt><dd>{{selectedTarget.snapshot.ssh_profile_id||'—'}}</dd><dt>结果</dt><dd>{{selectedTarget.state}}</dd><dt>退出码</dt><dd>{{selectedTarget.exit_code??'—'}}</dd></dl><h4>stdout</h4><pre>{{selectedTarget.stdout||'暂无输出'}}</pre><h4>stderr</h4><pre>{{selectedTarget.stderr||'暂无输出'}}</pre><KsButton @click="emit('tab','Logs')">查看设备日志</KsButton></template><p v-else>选择目标查看通道、结果与设备输出。</p></aside></div></template>
<template v-else-if="tab==='Logs'"><div class="native-filters"><KsInput v-model="logQuery" placeholder="搜索日志内容"/><select v-model="level"><option value="">所有等级</option><option>ERROR</option><option>WARN</option><option>INFO</option><option>DEBUG</option><option>TRACE</option></select><select :value="context.task_run||''" @change="emit('context','task_run',($event.target as HTMLSelectElement).value)"><option value="">所有 TaskRun</option><option v-for="task in tasks" :value="task.id" :key="task.id">{{task.taskId}} · {{task.value||task.id}}</option></select><KsButton size="small" @click="follow=!follow">{{follow?'跟随日志':'暂停跟随'}}</KsButton><KsButton size="small" @click="downloadLogs">下载当前结果</KsButton><KsButton v-if="context.task_run||context.target" size="small" @click="emit('context','task_run','');emit('context','target','');emit('context','attempt','')">清除上下文</KsButton></div><div v-if="selectedTarget" class="native-device-output"><b>{{selectedTarget.snapshot.name}} · {{selectedTarget.actual_transport}} · Attempt {{selectedTarget.attempt}}</b><pre>{{selectedTarget.stdout||'暂无 stdout'}}</pre><pre>{{selectedTarget.stderr||'暂无 stderr'}}</pre></div><div ref="logViewport" class="native-log-stream"><div v-for="(line,index) in filteredLogs" :key="line.id||index" class="native-log-line"><time>{{date(line.timestamp)}}</time><b :class="String(line.level).toLowerCase()">{{line.level}}</b><span><small>{{line.taskId||'execution'}} / {{line.taskRunId||'—'}}{{line.attemptNumber!==undefined?' · attempt '+(Number(line.attemptNumber)+1):''}}</small><code>{{line.message}}</code></span></div><div v-if="!filteredLogs.length" class="native-empty">当前筛选下尚无日志</div></div></template>
<NativePanelSlot v-else-if="tab==='Outputs & Artifacts'" name="outputs" :attach="attach"/>
<template v-else-if="tab==='Metrics'"><div class="native-section-title"><b>TASK METRICS</b><span>{{insights?.metrics_total||0}} samples</span></div><p v-if="insights?.metrics_error" class="native-error">指标未取得：{{insights.metrics_error}}</p><KsDataTable :data="insights?.metrics||[]" :total="insights?.metrics_total||0" :pageSize="50" :currentPage="Number(context.metric_page||1)" :selectable="false" :loadData="p=>emit('context','metric_page',String(p.page))"><KsTableColumn prop="name" label="指标"/><KsTableColumn prop="taskId" label="任务"/><KsTableColumn prop="type" label="类型"/><KsTableColumn prop="value" label="实测值"/><KsTableColumn label="单位"><template #default="{row}">{{row.unit||'未上报（不推断）'}}</template></KsTableColumn><KsTableColumn prop="timestamp" label="时间"/></KsDataTable></template>
<template v-else-if="tab==='Dependencies'"><div class="native-section-title"><b>EXECUTION LINEAGE</b></div><div v-for="item in insights?.relations||[]" :key="item.id" class="native-relation"><span>{{item.relation}}</span><button @click="emit('navigate','/flows/executions/'+item.id)">{{item.id}} →</button><span>{{item.state}}</span><time>{{date(item.created_at)}}</time></div><div v-if="!insights?.relations?.length" class="native-empty">未记录父子执行关联；不会根据执行时间推断关系。</div></template>
<NativePanelSlot v-else name="audit" :attach="attach"/>
</section></ElConfigProvider></template>
<script setup lang="ts">
import {computed,nextTick,ref,watch} from 'vue';import {ElConfigProvider} from 'element-plus';
import KsButton from '../../vendor/kestra/design-system/components/Basic/KsButton/KsButton.vue';import KsInput from '../../vendor/kestra/design-system/components/Form/KsInput.vue';import KsDataTable from '../../vendor/kestra/design-system/components/Data/KsDataTable/KsDataTable.vue';import KsTableColumn from '../../vendor/kestra/design-system/components/Data/KsTable/KsTableColumn.vue';import KsExecutionStatus from '../../vendor/kestra/design-system/components/Data/KsExecutionStatus/KsExecutionStatus.vue';import NativePanelSlot from './NativePanelSlot.vue';
const props=defineProps<{execution:any;logs:any[];tab:string;context:Record<string,string>;insights:any;error:string;busy:boolean;canExecute:boolean;attach:(name:string,el:HTMLElement|null)=>void}>(),emit=defineEmits(['tab','action','navigate','context']);
const engineState=computed(()=>props.execution.engine?.state?.current||'unknown'),tasks=computed<any[]>(()=>props.execution.engine?.taskRunList||[]),counts=computed(()=>props.execution.targets.reduce((a:any,t:any)=>{a[t.state]=(a[t.state]||0)+1;return a},{}));
const tabs=[['Overview','Overview'],['Targets','Targets'],['Task Runs','Gantt / Tasks'],['Logs','Logs'],['Outputs & Artifacts','Variables & Outputs'],['Audit / Context','Audit / Context']],more=[['Metrics','Metrics'],['Dependencies','Dependencies']];
const actions=[{id:'pause',label:'暂停',states:['RUNNING']},{id:'resume',label:'继续',states:['PAUSED']},{id:'kill',label:'终止',states:['RUNNING','PAUSED','CREATED','QUEUED']},{id:'restart',label:'全部重跑',states:['SUCCESS','FAILED','WARNING','KILLED']},{id:'retry-failed-targets',label:'重试失败目标',states:['SUCCESS','FAILED','WARNING','KILLED']}];
const graph=ref(false),matrix=ref(true),targetQuery=ref(''),targetState=ref(''),logQuery=ref(''),level=ref(''),follow=ref(true),logViewport=ref<HTMLElement|null>(null);
const selectedTask=computed(()=>tasks.value.find(t=>t.id===props.context.task_run)),selectedTarget=computed(()=>props.execution.targets.find((t:any)=>t.id===props.context.target));
const visibleTargets=computed(()=>props.execution.targets.filter((t:any)=>(!targetState.value||t.state===targetState.value)&&[t.id,t.snapshot?.name].join(' ').toLowerCase().includes(targetQuery.value.toLowerCase())));
const filteredLogs=computed(()=>props.logs.filter(l=>(!level.value||l.level===level.value)&&(!props.context.task_run||l.taskRunId===props.context.task_run)&&(!props.context.attempt||props.context.attempt==='all'||Number(l.attemptNumber)+1===Number(props.context.attempt))&&String(l.message||'').toLowerCase().includes(logQuery.value.toLowerCase())));
watch(()=>filteredLogs.value.length,async()=>{if(follow.value){await nextTick();if(logViewport.value)logViewport.value.scrollTop=logViewport.value.scrollHeight}});
const start=computed(()=>{const values=tasks.value.map(t=>Date.parse(t.state?.startDate)).filter(Number.isFinite);return values.length?Math.min(...values):Date.parse(props.execution.created_at)});
const end=computed(()=>{const values=tasks.value.flatMap(t=>[Date.parse(t.state?.endDate),Date.parse(t.state?.startDate)]).filter(Number.isFinite);return Math.max(start.value,...values)});
const date=(v:any)=>v&&Number.isFinite(new Date(v).getTime())?new Date(v).toLocaleString():'—';
function elapsed(state:any){const a=Date.parse(state?.startDate),b=Date.parse(state?.endDate);return Number.isFinite(a)&&Number.isFinite(b)?Math.max(0,(b-a)/1000).toFixed(1):'—'}
const ticks=computed(()=>Array.from({length:6},(_,i)=>((end.value-start.value)/1000*i/5).toFixed(1))),selectedError=computed(()=>{const attempts=selectedTask.value?.attempts||[],i=Number(props.context.attempt);return attempts[i>0?i-1:attempts.length-1]?.error?JSON.stringify(attempts[i>0?i-1:attempts.length-1].error,null,2):filteredLogs.value.filter(l=>l.level==='ERROR').at(-1)?.message||''});
let initiallySelected=false;watch(tasks,values=>{if(!initiallySelected&&values.length){initiallySelected=true;if(!props.context.task_run)emit('context','task_run',(values.find(t=>t.state?.current==='FAILED')||values[0]).id)}},{immediate:true});
function bar(t:any){const from=Date.parse(t.state?.startDate),to=Date.parse(t.state?.endDate)||end.value,span=Math.max(1,end.value-start.value);return {left:Math.max(0,(from-start.value)/span*100)+'%',width:Math.max(.5,(to-from)/span*100)+'%'}}
function downloadLogs(){const url=URL.createObjectURL(new Blob([filteredLogs.value.map(l=>`${l.timestamp||''} ${l.level||''} ${l.taskId||''} ${l.message||''}`).join('\n')],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download=props.execution.id+'.log';a.click();URL.revokeObjectURL(url)}
</script>
